use crate::api::client::ApiClient;
use crate::models::{ResultWithDefaultError, TimeEntry};
use crate::utilities;
use std::collections::BTreeMap;
use std::io::{self, Write};

const BILLING_INCREMENT_SECONDS: i64 = 15 * 60;
const MINIMUM_BILLING_SECONDS: i64 = 30 * 60;

pub struct InvoiceMonthlyCommand;

fn invoiced_seconds(duration: i64) -> i64 {
    if duration <= 0 {
        return 0;
    }

    let rounded = ((duration + BILLING_INCREMENT_SECONDS - 1) / BILLING_INCREMENT_SECONDS)
        * BILLING_INCREMENT_SECONDS;
    rounded.max(MINIMUM_BILLING_SECONDS)
}

fn monthly_totals(entries: &[TimeEntry]) -> BTreeMap<String, i64> {
    let mut totals = BTreeMap::new();
    for entry in entries {
        if !entry.billable || entry.is_running() || entry.stop.is_none() {
            continue;
        }

        let seconds = invoiced_seconds(entry.duration);
        if seconds == 0 {
            continue;
        }

        *totals
            .entry(entry.start.format("%Y-%m").to_string())
            .or_insert(0) += seconds;
    }
    totals
}

impl InvoiceMonthlyCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
        let entries = api_client
            .get_time_entries_filtered_minimal(since, until)
            .await?;
        let totals = monthly_totals(&entries);

        let mut stdout = io::BufWriter::new(io::stdout().lock());
        if totals.is_empty() {
            writeln!(stdout, "(no data)").expect("failed to print");
            return Ok(());
        }

        let total: i64 = totals.values().sum();
        for (month, seconds) in totals {
            writeln!(stdout, "{month}  {seconds}s").expect("failed to print");
        }
        writeln!(stdout, "Total  {total}s").expect("failed to print");
        Ok(())
    }
}

